insert into public.products (id, name, brand, category, family, price, stock, volume, color, notes, description, occasion, longevity, sweetness, freshness, intensity, image) values ('5cf099ae-af86-567c-97af-12f2730917eb', 'Afnan 9PM para hombres', 'Afnan', 'Masculino', 'Ámbar', 45000, 0, NULL, '#9566ac', 'manzana, canela, lavanda silvestre y bergamota', '9pm de Afnan es una fragancia de la familia olfativa Oriental Vainilla para Hombres. 9pm se lanzó en 2020. Las Notas de Salida son manzana, canela, lavanda silvestre y bergamota; las Notas de Corazón son flor de azahar del naranjo y lirio de los valles (muguete); las Notas de Fondo son vainilla, haba tonka, ámbar y pachulí.', 'Por confirmar', 'Por confirmar', NULL, NULL, NULL, 'imagenes/5cf099ae-af86-567c-97af-12f2730917eb.jpg') on conflict (id) do nothing;
insert into public.products (id, name, brand, category, family, price, stock, volume, color, notes, description, occasion, longevity, sweetness, freshness, intensity, image) values ('82f32b05-6251-56d7-bcff-24064d5ae21c', 'Al Haramain Amber Oud Gold Edition AI', 'Al Haramain', 'Unisex', 'Ámbar', 50000, 0, NULL, '#9566ac', 'bergamota y notas verdes', 'Amber Oud Gold Edition de Al Haramain Perfumes es una fragancia de la familia olfativa Oriental Vainilla para Hombres y Mujeres. Amber Oud Gold Edition se lanzó en 2024. Las Notas de Salida son bergamota y notas verdes; las Notas de Corazón son melón, piña, ámbar y Acorde goloso; las Notas de Fondo son vainilla, almizcle y notas amaderadas.', 'Por confirmar', 'Por confirmar', NULL, NULL, NULL, 'imagenes/82f32b05-6251-56d7-bcff-24064d5ae21c.jpg') on conflict (id) do nothing;
insert into public.products (id, name, brand, category, family, price, stock, volume, color, notes, description, occasion, longevity, sweetness, freshness, intensity, image) values ('1d54e87c-d13f-5288-8376-62c007548357', 'Armaf Club de Nuit Woman', 'Armaf', 'Femenino', 'Floral', 38000, 1, NULL, '#9566ac', 'naranja, bergamota, toronja (pomelo) y durazno (melocotón)', 'Club de Nuit Woman de Armaf es una fragancia de la familia olfativa Floral Frutal para Mujeres. Las Notas de Salida son naranja, bergamota, toronja (pomelo) y durazno (melocotón); las Notas de Corazón son rosa, jazmín, geranio y lichi; las Notas de Fondo son pachulí, almizcle, vainilla y vetiver.', 'Por confirmar', 'Por confirmar', NULL, NULL, NULL, 'imagenes/1d54e87c-d13f-5288-8376-62c007548357.jpg') on conflict (id) do nothing;
insert into public.products (id, name, brand, category, family, price, stock, volume, color, notes, description, occasion, longevity, sweetness, freshness, intensity, image) values ('07e9ffcf-7b3e-5d0f-9a5e-c1dc06974a7a', 'Azzure Hunted Elixir', 'Fragrance World', 'Por confirmar', 'Por confirmar', 25000, 0, 100, '#9566ac', 'Por confirmar', 'Azzure Hunted Elixir de Fragrance World. Eau de Parfum de 100 ml. Las notas aromáticas están pendientes de confirmar.', 'Por confirmar', 'Por confirmar', NULL, NULL, NULL, 'imagenes/07e9ffcf-7b3e-5d0f-9a5e-c1dc06974a7a.jpg') on conflict (id) do nothing;
insert into public.products (id, name, brand, category, family, price, stock, volume, color, notes, description, occasion, longevity, sweetness, freshness, intensity, image) values ('1325402c-8e08-57d2-bf0c-bf51e94d77c2', 'Emeer Lattafa perfume dorado', 'Lattafa', 'Unisex', 'Amaderada', 50000, 0, NULL, '#9566ac', 'limón (lima ácida), bergamota, esclarea y bayas de enebro', 'Emeer de Lattafa Perfumes es una fragancia de la familia olfativa Amaderada Aromática para Hombres y Mujeres. Emeer se lanzó en 2024. Las Notas de Salida son limón (lima ácida), bergamota, esclarea y bayas de enebro; las Notas de Corazón son té Blanco, sándalo, cardamomo y incienso de olíbano (franquincienso); las Notas de Fondo son ámbar gris, cedro, cachemira y pachulí.', 'Por confirmar', 'Por confirmar', NULL, NULL, NULL, 'imagenes/1325402c-8e08-57d2-bf0c-bf51e94d77c2.jpg') on conflict (id) do nothing;
insert into public.products (id, name, brand, category, family, price, stock, volume, color, notes, description, occasion, longevity, sweetness, freshness, intensity, image) values ('7e557c73-f88d-51db-9e24-8e29d73611d2', 'Emper Genius King of Fire azul', 'Emper', 'Por confirmar', 'Amaderada', 28000, 1, 100, '#9566ac', 'Mango, jengibre, limón, naranja, bergamota y frutos rojos / bayas rojas', 'Pirámide olfativa Notas de salida: Mango, jengibre, limón, naranja, bergamota y frutos rojos / bayas rojas. Notas de corazón: Cumarina, jazmín, cedro y un acorde frutal mediterráneo. Notas de fondo: Almizcle blanco, ámbar, vainilla de Madagascar, madera de oud y cipriol (nagarmotha). Características principales Concentración: Eau de Parfum (EDP) en presentación de 100 ml. Estilo: Fresco, frutal y con un fondo cálido y oriental gracias al oud y las maderas.', 'Por confirmar', 'Por confirmar', NULL, NULL, NULL, 'imagenes/7e557c73-f88d-51db-9e24-8e29d73611d2.jpg') on conflict (id) do nothing;
insert into public.products (id, name, brand, category, family, price, stock, volume, color, notes, description, occasion, longevity, sweetness, freshness, intensity, image) values ('6f41094e-a529-5f36-851d-dae7a344034f', 'Emper Genius Vesper', 'Emper', 'Por confirmar', 'Amaderada', 28000, 1, 100, '#9566ac', 'Bergamota de Calabria, mandarina, pomelo (toronja), yuzu, salvia esclarea y pimienta rosa', 'Genius Vesper es un Eau de Parfum (EDP) de 100 ml de la marca de perfumes Emper, caracterizado por su perfil aromático fresco, cítrico, amaderado y con un toque dulce. Notas Olfativas Notas de Salida: Bergamota de Calabria, mandarina, pomelo (toronja), yuzu, salvia esclarea y pimienta rosa. Notas de Corazón: Violeta de agua, pimienta de Sichuan, haba tonka, lavanda, geranio, vetiver, caramelo, elemí y pachulí. Notas de Fondo: Ámbar gris, ambroxan, madera de ámbar (amberwood), ládano.', 'Por confirmar', 'Por confirmar', NULL, NULL, NULL, 'imagenes/6f41094e-a529-5f36-851d-dae7a344034f.jpg') on conflict (id) do nothing;
insert into public.products (id, name, brand, category, family, price, stock, volume, color, notes, description, occasion, longevity, sweetness, freshness, intensity, image) values ('b5ea8163-d34f-5c1a-82ac-f30369c9f9ab', 'Extremely Unique Pista verde', 'Fragrance World', 'Por confirmar', 'Gourmand', 25000, 0, NULL, '#9566ac', 'Pistacho, helado cremoso, avellanas dulces y brotes de grosella negra', 'Extremely Unique Pista de Fragrance World es un perfume de la familia olfativa gourmand inspirado en el popular Yum Pistachio Gelato de Kayali. Notas Olfativas Salida: Pistacho, helado cremoso, avellanas dulces y brotes de grosella negra. Corazón: Vainilla, crema batida y flores suaves. Fondo: Haba tonka, almizcles cremosos y sándalo.', 'Por confirmar', 'Por confirmar', NULL, NULL, NULL, 'imagenes/b5ea8163-d34f-5c1a-82ac-f30369c9f9ab.jpg') on conflict (id) do nothing;
insert into public.products (id, name, brand, category, family, price, stock, volume, color, notes, description, occasion, longevity, sweetness, freshness, intensity, image) values ('e1a3a45c-216e-55ed-8c22-b9825d0890a6', 'Glacier Gold Maison Alhambra', 'Maison Alhambra', 'Masculino', 'Ámbar', 29000, 0, NULL, '#9566ac', 'cardamomo, bergamota, lavanda y menta', 'Glacier Gold de Maison Alhambra es una fragancia de la familia olfativa Oriental Especiada para Hombres. Esta fragancia es nueva. Glacier Gold se lanzó en 2025. Las Notas de Salida son cardamomo, bergamota, lavanda y menta; las Notas de Corazón son canela, flor de azahar del naranjo y comino; las Notas de Fondo son vainilla, ámbar, haba tonka y sándalo.', 'Por confirmar', 'Por confirmar', NULL, NULL, NULL, 'imagenes/e1a3a45c-216e-55ed-8c22-b9825d0890a6.jpg') on conflict (id) do nothing;
insert into public.products (id, name, brand, category, family, price, stock, volume, color, notes, description, occasion, longevity, sweetness, freshness, intensity, image) values ('d568559e-6a19-5238-a150-716756c72f69', 'iS Intense Fragrance World unisex', 'Fragrance World', 'Unisex', 'Por confirmar', 25000, 1, NULL, '#9566ac', 'grosellas negras, bergamota y mandarina', 'iS Intense de Fragrance World es una fragancia de la familia olfativa para Hombres y Mujeres. iS Intense se lanzó en 2021. Las Notas de Salida son grosellas negras, bergamota y mandarina; las Notas de Corazón son abrótano, osmanto (olivo oloroso), rosa de mayo y neroli; las Notas de Fondo son vainilla, pachulí y ambroxan. Inspiración: Sì Intense de Giorgio Armani (versión Eau de Parfum).', 'Por confirmar', 'Por confirmar', NULL, NULL, NULL, 'imagenes/d568559e-6a19-5238-a150-716756c72f69.jpg') on conflict (id) do nothing;
insert into public.products (id, name, brand, category, family, price, stock, volume, color, notes, description, occasion, longevity, sweetness, freshness, intensity, image) values ('1e56158d-8066-52f8-9f18-1d661c18131b', 'JIVI Eternal Rouge Metallic', 'JIVI', 'Por confirmar', 'Por confirmar', 30990, 1, NULL, '#9566ac', 'Por confirmar', 'Descripción y notas aromáticas pendientes de confirmar. Consúltanos por WhatsApp para conocer esta fragancia.', 'Por confirmar', 'Por confirmar', NULL, NULL, NULL, 'imagenes/1e56158d-8066-52f8-9f18-1d661c18131b.jpg') on conflict (id) do nothing;
insert into public.products (id, name, brand, category, family, price, stock, volume, color, notes, description, occasion, longevity, sweetness, freshness, intensity, image) values ('f23fea9e-a6b0-5d76-825e-9f4ca025dfb7', 'John Gustav Homme Scandant Le Parfum', 'Por confirmar', 'Masculino', 'Gourmand', 30000, 1, NULL, '#9566ac', 'Jazmín, geranio, caramelo y vainilla', 'Inspiración: Es una fragancia árabe alternativa o "inspirada" en Scandal Pour Homme Le Parfum de Jean Paul Gaultier. Familia olfativa / Notas: Notas de salida: Jazmín /Geranio Notas de corazón: Caramelo Notas de fondo: Vainilla (perfil dulce, cálido y gourmand)', 'Por confirmar', 'Por confirmar', NULL, NULL, NULL, 'imagenes/f23fea9e-a6b0-5d76-825e-9f4ca025dfb7.jpg') on conflict (id) do nothing;
insert into public.products (id, name, brand, category, family, price, stock, volume, color, notes, description, occasion, longevity, sweetness, freshness, intensity, image) values ('a2e28a9c-4ed2-5bfe-89fa-5c6e3ad9b565', 'Just Aswad negro', 'Fragrance World', 'Masculino', 'Aromática', 26990, 0, NULL, '#9566ac', 'nuez moscada, cardamomo, canela y pomelo', 'Just Aswad de Fragrance World es una fragancia aromática fougère para hombres. Fue lanzada en 2023. Sus notas de salida son nuez moscada, cardamomo, canela y pomelo; la nota de corazón es lavanda; y las notas de fondo son regaliz, sándalo, ámbar, pachulí y vetiver.', 'Por confirmar', 'Por confirmar', NULL, NULL, NULL, 'imagenes/a2e28a9c-4ed2-5bfe-89fa-5c6e3ad9b565.jpg') on conflict (id) do nothing;
insert into public.products (id, name, brand, category, family, price, stock, volume, color, notes, description, occasion, longevity, sweetness, freshness, intensity, image) values ('3d436a54-34bf-59c5-91cc-bdb1982b5e17', 'Khair Confection', 'Paris Corner', 'Femenino', 'Gourmand', 30990, 0, NULL, '#9566ac', 'pera y crema batida', 'Khair Confection de PARIS CORNER es una fragancia de la familia olfativa Floral Frutal Gourmand para Mujeres. Esta fragancia es nueva. Khair Confection se lanzó en 2024. Las Notas de Salida son pera y crema batida; las Notas de Corazón son cachemira, jazmín y ylang-ylang; las Notas de Fondo son malvavisco (bombón), vainilla y sándalo.', 'Por confirmar', 'Por confirmar', NULL, NULL, NULL, 'imagenes/3d436a54-34bf-59c5-91cc-bdb1982b5e17.jpg') on conflict (id) do nothing;
insert into public.products (id, name, brand, category, family, price, stock, volume, color, notes, description, occasion, longevity, sweetness, freshness, intensity, image) values ('0890965c-a31d-5e80-b2ee-3943c312738b', 'La Nuit Pendora Scents Mujer', 'Pendora Scents', 'Femenino', 'Gourmand', 27000, 1, NULL, '#9566ac', 'naranja tangerina, pera y bergamota', 'La Nuit Pendora de Pendora Scents es una fragancia de la familia olfativa Floral Frutal Gourmand para Mujeres. La Nuit Pendora se lanzó en 2020. Las Notas de Salida son naranja tangerina, pera y bergamota; las Notas de Corazón son orquídea de vainilla, rosa negra, fresa y maracuyá (fruta de la pasión); las Notas de Fondo son regaliz, vainilla, incienso, pachulí, cumarina, praliné, lichi, caramelo, café y papiro de Egipto.', 'Por confirmar', 'Por confirmar', NULL, NULL, NULL, 'imagenes/0890965c-a31d-5e80-b2ee-3943c312738b.jpg') on conflict (id) do nothing;
insert into public.products (id, name, brand, category, family, price, stock, volume, color, notes, description, occasion, longevity, sweetness, freshness, intensity, image) values ('48e95e0c-3491-5fb0-861a-ca3665a28dfe', 'Lady Presidente Queen Of Fire', 'Emper', 'Por confirmar', 'Ámbar', 30000, 1, 80, '#9566ac', 'Por confirmar', 'Lady Presidente Queen of Fire de Emper es un perfume Eau de Parfum (EDP) de 80 ml con un aroma intenso frutal, ambarado y amaderado, inspirado en la famosa fragancia God of Fire.', 'Por confirmar', 'Por confirmar', NULL, NULL, NULL, 'imagenes/48e95e0c-3491-5fb0-861a-ca3665a28dfe.jpg') on conflict (id) do nothing;
insert into public.products (id, name, brand, category, family, price, stock, volume, color, notes, description, occasion, longevity, sweetness, freshness, intensity, image) values ('6483bbf2-561e-52df-bb78-df7212f279b3', 'Lattafa Fakhar Platin perfume', 'Lattafa', 'Unisex', 'Aromática', 35000, 0, NULL, '#9566ac', 'bergamota, pimienta rosa y cardamomo', 'Fakhar Platin de Lattafa Perfumes es una fragancia de la familia olfativa Aromática Fougère para Hombres y Mujeres. Esta fragancia es nueva. Fakhar Platin se lanzó en 2025. Las Notas de Salida son bergamota, pimienta rosa y cardamomo; las Notas de Corazón son guayaba, lavanda y jengibre; las Notas de Fondo son incienso, palo santo y sándalo.', 'Por confirmar', 'Por confirmar', NULL, NULL, NULL, 'imagenes/6483bbf2-561e-52df-bb78-df7212f279b3.jpg') on conflict (id) do nothing;
insert into public.products (id, name, brand, category, family, price, stock, volume, color, notes, description, occasion, longevity, sweetness, freshness, intensity, image) values ('f58abc47-0c90-5647-bf3f-99437d74a9c6', 'Lattafa Hayaati Florence', 'Lattafa', 'Femenino', 'Gourmand', 27990, 1, NULL, '#9566ac', 'Notas florales, notas dulces, cítricos, pomelo rosado y almizcle', 'Hayaati Florence de Lattafa Perfumes es una fragancia de la familia olfativa Floral Frutal Gourmand para Mujeres. Hayaati Florence se lanzó en 2023. La fragancia contiene notas florales, notas dulces, cítricos, toronja (pomelo) rosada y almizcle.', 'Por confirmar', 'Por confirmar', NULL, NULL, NULL, 'imagenes/f58abc47-0c90-5647-bf3f-99437d74a9c6.jpg') on conflict (id) do nothing;
insert into public.products (id, name, brand, category, family, price, stock, volume, color, notes, description, occasion, longevity, sweetness, freshness, intensity, image) values ('a2a3dcbb-906b-5b53-9d16-b829800a1993', 'Lattafa Hayaati Gold Elixir', 'Lattafa', 'Unisex', 'Por confirmar', 27990, 0, NULL, '#9566ac', 'bergamota, pomelo y grosella negra', 'Hayaati Gold Elixir de Lattafa Perfumes es una fragancia para mujeres y hombres. Sus notas de salida son bergamota, pomelo y grosella negra; las notas de corazón son cuero, melocotón y azafrán; y las notas de fondo son vainilla, ámbar, almizcle y vetiver.', 'Por confirmar', 'Por confirmar', NULL, NULL, NULL, 'imagenes/a2a3dcbb-906b-5b53-9d16-b829800a1993.jpg') on conflict (id) do nothing;
insert into public.products (id, name, brand, category, family, price, stock, volume, color, notes, description, occasion, longevity, sweetness, freshness, intensity, image) values ('6a82f49f-c66b-5b65-bfe0-92f9d2c85331', 'Lattafa Opulent dubai', 'Lattafa', 'Unisex', 'Floral', 35000, 1, NULL, '#9566ac', 'mango, pomelo, limón y jengibre', 'Opulent Dubai de Lattafa Perfumes es una fragancia floral oriental para mujeres y hombres. Se trata de una fragancia nueva, lanzada en 2025. Sus notas de salida son mango, pomelo, limón y jengibre; las notas de corazón son jazmín, cedro y violeta; y las notas de fondo son notas amaderadas, ámbar gris, musgo de roble y benjuí.', 'Por confirmar', 'Por confirmar', NULL, NULL, NULL, 'imagenes/6a82f49f-c66b-5b65-bfe0-92f9d2c85331.jpg') on conflict (id) do nothing;
insert into public.products (id, name, brand, category, family, price, stock, volume, color, notes, description, occasion, longevity, sweetness, freshness, intensity, image) values ('c80951d6-e568-5f88-b408-46dd34c7c0c8', 'Lattafa Qaed Al Fursan negro', 'Lattafa', 'Unisex', 'Amaderada', 25000, 0, NULL, '#9566ac', 'piña y azafrán', 'Qaed Al Fursan de Lattafa Perfumes es una fragancia oriental amaderada para mujeres y hombres. Qaed Al Fursan se lanzó en 2016. Las notas de salida son piña y azafrán; las notas de corazón son abeto balsámico y jazmín; las notas de fondo son cedro, ámbar y madera de oud.', 'Por confirmar', 'Por confirmar', NULL, NULL, NULL, 'imagenes/c80951d6-e568-5f88-b408-46dd34c7c0c8.jpg') on conflict (id) do nothing;
insert into public.products (id, name, brand, category, family, price, stock, volume, color, notes, description, occasion, longevity, sweetness, freshness, intensity, image) values ('7dd5f137-1c69-5670-b2ff-1aef9479cb7e', 'Lattafa Qaed Al Fursan Unlimited', 'Lattafa', 'Por confirmar', 'Por confirmar', 27990, 0, NULL, '#9566ac', 'Por confirmar', 'Descripción y notas aromáticas pendientes de confirmar. Consúltanos por WhatsApp para conocer esta fragancia.', 'Por confirmar', 'Por confirmar', NULL, NULL, NULL, 'imagenes/7dd5f137-1c69-5670-b2ff-1aef9479cb7e.jpg') on conflict (id) do nothing;
insert into public.products (id, name, brand, category, family, price, stock, volume, color, notes, description, occasion, longevity, sweetness, freshness, intensity, image) values ('00c6d942-fd07-5128-9211-acb0a8b3550a', 'Lattafa Teriaq Intense perfume', 'Lattafa', 'Unisex', 'Ámbar', 45000, 0, NULL, '#9566ac', 'azafrán y bergamota', 'Teriaq Intense de Lattafa Perfumes es una fragancia de la familia olfativa Oriental Especiada para Hombres y Mujeres. Esta fragancia es nueva. Teriaq Intense se lanzó en 2024. La Nariz detrás de esta fragancia es Quentin Bisch. Las Notas de Salida son azafrán y bergamota; las Notas de Corazón son Licor de ciruela y canela; las Notas de Fondo son ámbar, haba tonka y benjuí.', 'Por confirmar', 'Por confirmar', NULL, NULL, NULL, 'imagenes/00c6d942-fd07-5128-9211-acb0a8b3550a.jpg') on conflict (id) do nothing;
insert into public.products (id, name, brand, category, family, price, stock, volume, color, notes, description, occasion, longevity, sweetness, freshness, intensity, image) values ('f4c4473e-32a2-57b4-b3ab-76c5fef2abb3', 'Lattafa The Kingdom For Men', 'Lattafa', 'Masculino', 'Aromática', 40000, 0, NULL, '#9566ac', 'Menta, lavanda, salvia, vainilla, tabaco, flor de azahar, haba tonka y benjuí', 'Perfil de aroma: Es una fragancia dulce, aromática y densa, ideal para climas templados o fríos y salidas nocturnas. Notas: Abre con una ráfaga fresca y limpia de menta, lavanda y salvia. En el corazón, se vuelve densa y seductora con notas de vainilla, tabaco y flor de azahar, finalizando en una base resinosa de haba tonka y benjuí.', 'Noche · clima templado o frío', 'Por confirmar', NULL, NULL, NULL, 'imagenes/f4c4473e-32a2-57b4-b3ab-76c5fef2abb3.jpg') on conflict (id) do nothing;
insert into public.products (id, name, brand, category, family, price, stock, volume, color, notes, description, occasion, longevity, sweetness, freshness, intensity, image) values ('6ba26d3c-61f0-5978-9cf8-fb8e4c87898c', 'Liquid Brun perfume marron', 'French Avenue', 'Masculino', 'Amaderada', 45000, 1, 100, '#9566ac', 'Canela, azahar, cardamomo, bergamota, vainilla bourbon, elemí, praliné, ambroxan, almizcle y guayaco', 'Liquid Brun Eau de Parfum 100 ml de French Avenue es un perfume masculino con un aroma dulce y amaderado. Su dulzor lo hace cálido y muy fácil de llevar. La salida es cálida y especiada: canela, azahar, cardamomo y bergamota. Luego el aroma se vuelve más dulce con vainilla bourbon y elemí. Al final, praliné, ambroxan, almizcle y madera de guayaco le dan profundidad y hacen que el aroma dure. Está pensado para cuando quieres causar impresión: citas, celebraciones, matrimonios o salidas nocturna', 'Noche', 'Por confirmar', NULL, NULL, NULL, 'imagenes/6ba26d3c-61f0-5978-9cf8-fb8e4c87898c.jpg') on conflict (id) do nothing;
insert into public.products (id, name, brand, category, family, price, stock, volume, color, notes, description, occasion, longevity, sweetness, freshness, intensity, image) values ('1923c8c9-82ee-5a47-a102-68de81b0e84b', 'Maison Alhambra La Rouge Baroque rosa', 'Maison Alhambra', 'Unisex', 'Ámbar', 26990, 1, NULL, '#9566ac', 'azafrán, pera y mandarina', 'Baroque Rouge 540 de Maison Alhambra es una fragancia de la familia olfativa Oriental para Hombres y Mujeres. Baroque Rouge 540 se lanzó en 2021. Las Notas de Salida son azafrán, pera y mandarina; las Notas de Corazón son jazmín, ylang-ylang y azucena; las Notas de Fondo son ámbar, madera de cachemira y almizcle.', 'Por confirmar', 'Por confirmar', NULL, NULL, NULL, 'imagenes/1923c8c9-82ee-5a47-a102-68de81b0e84b.jpg') on conflict (id) do nothing;
insert into public.products (id, name, brand, category, family, price, stock, volume, color, notes, description, occasion, longevity, sweetness, freshness, intensity, image) values ('ef69ec5e-9a68-531e-a76c-2b8b68a97388', 'Maison Alhambra So Candid Rouge', 'Maison Alhambra', 'Femenino', 'Gourmand', 25000, 1, 85, '#9566ac', 'Frambuesa, mandarina, pimienta rosa', 'Maison Alhambra So Candid Rouge EDP 85 ml es una fragancia femenina seductora y envolvente que combina dulzura y elegancia. Su aroma floral gourmand deja una estela cálida y sofisticada, perfecta para resaltar la feminidad con carácter y estilo. Inspirado en So Scandal! de Jean Paul Gaultier. Notas de salida: Frambuesa, mandarina, pimienta rosa. Notas de corazón: Rosa, jazmín, caramelo. Notas de fondo: Vainilla, almizcle, pachulí. Aroma: Dulce Género: Mujer Ocasión: Noche', 'Noche', 'Por confirmar', NULL, NULL, NULL, 'imagenes/ef69ec5e-9a68-531e-a76c-2b8b68a97388.jpg') on conflict (id) do nothing;
insert into public.products (id, name, brand, category, family, price, stock, volume, color, notes, description, occasion, longevity, sweetness, freshness, intensity, image) values ('9c71e27c-d5e3-56d4-b8b0-664dfd5daa60', 'Maison Alhambra Vogue Night azul', 'Maison Alhambra', 'Por confirmar', 'Por confirmar', 28990, 1, NULL, '#9566ac', 'Por confirmar', 'Descripción y notas aromáticas pendientes de confirmar. Consúltanos por WhatsApp para conocer esta fragancia.', 'Por confirmar', 'Por confirmar', NULL, NULL, NULL, 'imagenes/9c71e27c-d5e3-56d4-b8b0-664dfd5daa60.jpg') on conflict (id) do nothing;
insert into public.products (id, name, brand, category, family, price, stock, volume, color, notes, description, occasion, longevity, sweetness, freshness, intensity, image) values ('b303b521-5f5a-58fe-a687-bb11eac70470', 'Malika Red Nusuk', 'Nusuk', 'Femenino', 'Por confirmar', 31990, 1, NULL, '#9566ac', 'Por confirmar', 'Nusuk Malika Pour Femme es una fragancia cautivadora que fusiona frescura, elegancia y calidez en una composición única. Diseñada para la mujer sofisticada y segura de sí misma, su aroma envuelve los sentidos con un equilibrio perfecto entre lo moderno y lo atemporal.', 'Por confirmar', 'Por confirmar', NULL, NULL, NULL, 'imagenes/b303b521-5f5a-58fe-a687-bb11eac70470.jpg') on conflict (id) do nothing;
insert into public.products (id, name, brand, category, family, price, stock, volume, color, notes, description, occasion, longevity, sweetness, freshness, intensity, image) values ('586eaa72-dad0-5331-bd2c-7aa9abdd1d63', 'Minya Caramel Dulce mujer', 'Paris Corner', 'Femenino', 'Ámbar', 30990, 1, NULL, '#9566ac', 'palomitas de maíz y mantequilla', 'Minya Caramel Dulce de PARIS CORNER es una fragancia de la familia olfativa Oriental Vainilla para Mujeres. Esta fragancia es nueva. Minya Caramel Dulce se lanzó en 2025. Las Notas de Salida son palomitas de maíz y mantequilla; las Notas de Corazón son castaña, benjuí y chocolate; las Notas de Fondo son caramelo, vainilla y azúcar moreno.', 'Por confirmar', 'Por confirmar', NULL, NULL, NULL, 'imagenes/586eaa72-dad0-5331-bd2c-7aa9abdd1d63.jpg') on conflict (id) do nothing;
insert into public.products (id, name, brand, category, family, price, stock, volume, color, notes, description, occasion, longevity, sweetness, freshness, intensity, image) values ('4ef93e92-2ec6-572d-8d6d-d3f2852a6b04', 'Optimystic Paradox Fragrance World Mujer', 'Fragrance World', 'Femenino', 'Gourmand', 27990, 1, NULL, '#9566ac', 'mandarina, bergamota y pera', 'Optimystic Paradox de Fragrance World es una fragancia de la familia olfativa Floral Frutal Gourmand para Mujeres. Optimystic Paradox se lanzó en 2022. Las Notas de Salida son mandarina, bergamota y pera; las Notas de Corazón son flor de azahar del naranjo, neroli y jazmín sambac (sampaguita); las Notas de Fondo son vainilla Bourbon, almizcle blanco, benjuí y ámbar.', 'Por confirmar', 'Por confirmar', NULL, NULL, NULL, 'imagenes/4ef93e92-2ec6-572d-8d6d-d3f2852a6b04.jpg') on conflict (id) do nothing;
insert into public.products (id, name, brand, category, family, price, stock, volume, color, notes, description, occasion, longevity, sweetness, freshness, intensity, image) values ('10435e93-72c2-52d4-a860-cf3021e660e1', 'Paris Corner Khair Fusion rosa', 'Paris Corner', 'Por confirmar', 'Por confirmar', 30990, 0, NULL, '#9566ac', 'Por confirmar', 'Descripción y notas aromáticas pendientes de confirmar. Consúltanos por WhatsApp para conocer esta fragancia.', 'Por confirmar', 'Por confirmar', NULL, NULL, NULL, 'imagenes/10435e93-72c2-52d4-a860-cf3021e660e1.jpg') on conflict (id) do nothing;
insert into public.products (id, name, brand, category, family, price, stock, volume, color, notes, description, occasion, longevity, sweetness, freshness, intensity, image) values ('2c0e9d99-b194-556b-9387-493abc48b2c2', 'Paris Corner Marshmallow Blush', 'Paris Corner', 'Unisex', 'Por confirmar', 25000, 0, NULL, '#9566ac', 'fresa, frambuesa y limón (lima ácida)', 'Marshmallow Blush de PARIS CORNER es una fragancia de la familia olfativa para Hombres y Mujeres. Esta fragancia es nueva. Marshmallow Blush se lanzó en 2025. Las Notas de Salida son fresa, frambuesa y limón (lima ácida); las Notas de Corazón son ambroxan y flor de azahar del naranjo; las Notas de Fondo son malvavisco (bombón) y almizcle.', 'Por confirmar', 'Por confirmar', NULL, NULL, NULL, 'imagenes/2c0e9d99-b194-556b-9387-493abc48b2c2.jpg') on conflict (id) do nothing;
insert into public.products (id, name, brand, category, family, price, stock, volume, color, notes, description, occasion, longevity, sweetness, freshness, intensity, image) values ('8118b7a3-dc1e-5868-9719-e4034cea637b', 'Rave Luxure Woman EDP', 'Lattafa', 'Femenino', 'Floral', 25990, 0, NULL, '#9566ac', 'naranja tangerina, naranja, pimienta negra y frambuesa', 'Rava Luxuré de Lattafa Perfumes es una fragancia de la familia olfativa Floral para Mujeres. Rava Luxuré se lanzó en 2023. Las Notas de Salida son naranja tangerina, naranja, pimienta negra y frambuesa; las Notas de Corazón son jazmín, flores blancas y rosa; las Notas de Fondo son fresia, pachulí y vainilla.', 'Por confirmar', 'Por confirmar', NULL, NULL, NULL, 'imagenes/8118b7a3-dc1e-5868-9719-e4034cea637b.jpg') on conflict (id) do nothing;
insert into public.products (id, name, brand, category, family, price, stock, volume, color, notes, description, occasion, longevity, sweetness, freshness, intensity, image) values ('107cf767-b05c-5c31-8691-bcbb730bb0d1', 'Scandant By Night', 'Fragrance World', 'Femenino', 'Gourmand', 25000, 0, NULL, '#9566ac', 'Miel, naranja amarga, cítricos, frutas, flores blancas y vainilla', 'Scandant By Night de Fragrance World es una fragancia femenina creada alrededor de un perfil intenso, dulce y profundamente seductor. La combinación de miel, naranja amarga y cítricos aporta un comienzo luminoso pero muy dulce, mientras las frutas y flores blancas construyen un corazón voluptuoso. El resultado es un perfume amielado, floral, afrutado, avainillado y gourmand, pensado especialmente para quienes buscan una fragancia femenina con mucha presencia.', 'Por confirmar', 'Por confirmar', NULL, NULL, NULL, 'imagenes/107cf767-b05c-5c31-8691-bcbb730bb0d1.jpg') on conflict (id) do nothing;
insert into public.products (id, name, brand, category, family, price, stock, volume, color, notes, description, occasion, longevity, sweetness, freshness, intensity, image) values ('c9bd4252-3a05-49d0-b4c5-2fbee58d7c66', 'The White cloud', 'Maison Alhambra', 'Unisex', 'Ámbar', 25000, 0, NULL, '#9566ac', 'de almendra amarga', 'The White cloud de maison alhambra es una fragancia de la familia olfativa oriental vainilla, para hombres y mujeres. Sus notas de salida son de almendra amarga ; notas de corazón son de vainilla y notas florales ;notas de fondo son absoluto vainilla, haba tonka y sandalo.', 'Por confirmar', 'Por confirmar', NULL, NULL, NULL, 'imagenes/c9bd4252-3a05-49d0-b4c5-2fbee58d7c66.jpg') on conflict (id) do nothing;
insert into public.products (id, name, brand, category, family, price, stock, volume, color, notes, description, occasion, longevity, sweetness, freshness, intensity, image) values ('d0799722-cd00-5263-a8b8-58abbb6faccd', 'Veneno bianco frech avenue', 'French Avenue', 'Por confirmar', 'Gourmand', 50000, 1, NULL, '#9566ac', 'Leche, neroli y bergamota (dan una apertura cremosa y ligeramente cítrica)', 'Es una fragancia de la familia floral-oriental/gourmand que destaca por su carácter veraniego, cremoso y tropical. Su pirámide olfativa se compone de: Notas de Salida: Leche, neroli y bergamota (dan una apertura cremosa y ligeramente cítrica). Notas de Corazón: Flores blancas, flor de tiaré e ylang-ylang (aportan un bouquet floral exótico y solar). Notas de Fondo: Coco, vainilla, ládano y madera de gaiac (crean una estela dulce, cálida y sofisticada que recuerda a un bronceador de lujo).', 'Verano', 'Por confirmar', NULL, NULL, NULL, 'imagenes/d0799722-cd00-5263-a8b8-58abbb6faccd.jpg') on conflict (id) do nothing;
